--
-- Table structure for table `menu_item`
--

DROP TABLE IF EXISTS `menu_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `menu_item` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键编号',
  `menu_id` int NOT NULL COMMENT '菜单编号',
  `recipe_id` int DEFAULT NULL COMMENT '食谱编号',
  `meal_date` date NOT NULL COMMENT '餐日期',
  `meal_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '餐类型',
  `is_locked` tinyint(1) NOT NULL COMMENT '是否锁定',
  `is_cooked` tinyint(1) NOT NULL COMMENT '是否已烹饪',
  `cook_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '烹饪模式',
  `estimated_cost` float DEFAULT NULL COMMENT '预估成本(元)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `rejected_recipe_ids` text COLLATE utf8mb4_unicode_ci COMMENT '本餐被「换一道」换掉的菜谱 id JSON 数组, 避免来回横跳',
  PRIMARY KEY (`id`),
  KEY `recipe_id` (`recipe_id`),
  KEY `ix_menu_item_menu_date` (`menu_id`,`meal_date`),
  CONSTRAINT `menu_item_ibfk_1` FOREIGN KEY (`menu_id`) REFERENCES `menu` (`id`) ON DELETE CASCADE,
  CONSTRAINT `menu_item_ibfk_2` FOREIGN KEY (`recipe_id`) REFERENCES `recipe` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=446 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='菜单项';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `menu_item`
--

