  `cook_minutes` int DEFAULT NULL COMMENT '烹饪分钟',
  `calories` int DEFAULT NULL COMMENT '卡路里',
  `protein_g` float DEFAULT NULL COMMENT '蛋白质克',
  `carb_g` float DEFAULT NULL COMMENT '碳水克',
  `fat_g` float DEFAULT NULL COMMENT '脂肪克',
  `steps` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '步骤',
  `source` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品类: 荤菜/素菜/汤羹/主食/面食/凉菜/小吃',
  `main_ingredient` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主料, 判断连续两餐不重样的最小粒度',
  `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '场景标签 JSON 数组',
  `flavor_tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '味型标签 JSON 数组',
  `spice_level` int NOT NULL DEFAULT '0' COMMENT '辣度 0-4',
  `is_light` tinyint(1) NOT NULL DEFAULT '0' COMMENT '轻食: 深夜只从这里挑',
  `cover_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果卡角标短文本',
  `quick_steps` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '极简做法 JSON 数组, 3-5 步',
  `meal_slots` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '适合餐次 JSON 数组: breakfast/lunch/dinner/late_night',
  `meat_type` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '荤型: none/egg_dairy/poultry/red_meat/seafood/mixed',
  `tools` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所需厨具 JSON 数组: wok/steamer/oven/air_fryer/...',
  `season` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '时令 JSON 数组: spring/summer/autumn/winter',
  `enrich_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '富集状态: pending/partial/done/failed',
  `enriched_at` datetime DEFAULT NULL COMMENT '最近一次富集时间',
  `enrich_source` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段来源: seed/rule/llm/manual',
  `steps_source` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '做法来源: seed/rule/llm/manual',
  `is_dish` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否是一道正经的菜: 0=调味品/饮品/甜品/半成品加工, 不参与「饭决」决策; 1=正常候选',
  PRIMARY KEY (`id`),
  KEY `ix_recipe_enrich_status` (`enrich_status`)
) ENGINE=InnoDB AUTO_INCREMENT=397 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='食谱';
