--
-- Table structure for table `recipe_enrich_log`
--

DROP TABLE IF EXISTS `recipe_enrich_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recipe_enrich_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `recipe_id` int DEFAULT NULL COMMENT 'EXPAND 成功前为 NULL',
  `dish_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜名(冗余)',
  `kind` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'fields' COMMENT 'fields/steps/expand',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ok/skipped/failed',
  `provider` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'llm 链里真正用上的客户端名',
  `fields` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本次写入的字段名',
  `message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败原因/备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `recipe_id` (`recipe_id`),
  KEY `ix_recipe_enrich_created` (`created_at`),
  CONSTRAINT `recipe_enrich_log_ibfk_1` FOREIGN KEY (`recipe_id`) REFERENCES `recipe` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='菜品富集流水: 定时任务无人值守, 过程必须可追溯';
